INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES

-- SUBTOPIC 1: Antacids & PPIs (10 MCQs)
('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antacids & PPIs','easy','mcq','What is the primary mechanism of action of proton pump inhibitors (PPIs) such as omeprazole?','["A. Irreversibly inhibit the H+/K+ ATPase proton pump","B. Block H2 receptors on parietal cells","C. Neutralise gastric acid directly","D. Stimulate prostaglandin synthesis in gastric mucosa"]','A','PPIs such as omeprazole irreversibly inhibit the H+/K+ ATPase proton pump on the luminal surface of gastric parietal cells. This blocks the final step of acid secretion, making PPIs the most potent acid suppressants available. They require an acidic environment to be activated and should be taken 30 minutes before meals.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antacids & PPIs','medium','mcq','A patient on warfarin is started on cimetidine for peptic ulcer disease. What is the most clinically important consequence of this combination?','["A. Reduced anticoagulant effect of warfarin due to enzyme induction","B. Increased warfarin levels due to CYP450 inhibition by cimetidine","C. Reduced gastric pH impairing warfarin absorption","D. Cimetidine displaces warfarin from plasma protein binding only"]','B','Cimetidine is a potent inhibitor of CYP450 enzymes (particularly CYP1A2, CYP2C9, CYP2D6, CYP3A4). Warfarin is metabolised by CYP2C9, so co-administration with cimetidine leads to elevated warfarin levels and increased bleeding risk. Other H2 blockers (ranitidine, famotidine) have far fewer drug interactions and are preferred when combination therapy is needed.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antacids & PPIs','medium','mcq','Which of the following adverse effects is most associated with long-term PPI use?','["A. Hyperkalaemia and metabolic alkalosis","B. Hypercalcaemia and nephrolithiasis","C. Hypomagnesaemia, vitamin B12 deficiency, and increased fracture risk","D. Iron overload and haemochromatosis"]','C','Long-term PPI use is associated with hypomagnesaemia (due to impaired active magnesium transport in the gut), vitamin B12 deficiency (reduced intrinsic factor-independent absorption requiring acidic conditions), increased risk of hip fractures (reduced calcium absorption), and Clostridioides difficile infection. These effects are dose- and duration-dependent.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antacids & PPIs','easy','mcq','Which antacid is most likely to cause constipation?','["A. Magnesium trisilicate","B. Sodium bicarbonate","C. Calcium carbonate only","D. Aluminium hydroxide"]','D','Aluminium-containing antacids (e.g., aluminium hydroxide) typically cause constipation due to the astringent effect of aluminium ions on the gut. In contrast, magnesium-containing antacids tend to cause diarrhoea. Many proprietary antacids combine both to achieve a balance in bowel habits.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antacids & PPIs','hard','mcq','A patient with HIV is started on omeprazole. Which antiretroviral drug absorption is most significantly reduced?','["A. Atazanavir","B. Tenofovir","C. Efavirenz","D. Lopinavir"]','A','Atazanavir (a protease inhibitor) requires an acidic gastric environment for adequate absorption. PPIs substantially raise gastric pH and can reduce atazanavir absorption by up to 75%, leading to sub-therapeutic levels and treatment failure. The co-administration of PPIs with atazanavir is generally contraindicated. Ketoconazole, iron, and calcium also have reduced absorption with PPIs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antacids & PPIs','medium','mcq','Sucralfate exerts its cytoprotective effect primarily by which mechanism?','["A. Inhibiting H+/K+ ATPase in parietal cells","B. Forming a viscous protective barrier over ulcer craters in acidic conditions","C. Stimulating bicarbonate secretion from parietal cells","D. Blocking H2 receptors and reducing acid output by 70%"]','B','Sucralfate is an aluminium salt of sucrose octasulphate. In an acidic environment (pH < 4), it polymerises and forms a viscous gel that adheres to ulcer craters, providing a physical barrier against acid, pepsin, and bile. It also stimulates prostaglandin and bicarbonate secretion. It should be taken before meals and does not require systemic absorption to work.','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antacids & PPIs','hard','mcq','Why should PPIs be taken 30 minutes before the first meal of the day?','["A. Food delays gastric emptying and reduces PPI absorption from the small intestine","B. PPIs bind to food particles and are inactivated if taken with food","C. PPIs are activated by acid but require active proton pumps that are stimulated by meal-related acid secretion","D. The renal clearance of PPIs is highest in the fasting state"]','C','PPIs are prodrugs that are activated in the acidic secretory canaliculi of parietal cells. Proton pumps are most active during meal-stimulated acid secretion. Taking a PPI 30 minutes before a meal ensures the drug is absorbed and available in the circulation when parietal cells are maximally stimulated by food, giving the highest proportion of active pumps available for irreversible inhibition.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antacids & PPIs','easy','mcq','Misoprostol is a synthetic analogue of which endogenous mediator that protects the gastric mucosa?','["A. Histamine","B. Gastrin","C. Somatostatin","D. Prostaglandin E1 (PGE1)"]','D','Misoprostol is a synthetic PGE1 analogue. It protects the gastric mucosa by increasing mucus and bicarbonate secretion, enhancing mucosal blood flow, and inhibiting acid secretion (acting on EP3 receptors on parietal cells). It is primarily used to prevent NSAID-induced gastric ulcers. Side effects include diarrhoea and uterine contractions (making it useful in obstetrics but contraindicated in pregnancy for GI indications).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antacids & PPIs','medium','mcq','H2 receptor blockers reduce gastric acid secretion by approximately what percentage?','["A. 70%","B. 50%","C. 30%","D. 90%"]','A','H2 receptor antagonists (e.g., ranitidine, famotidine, cimetidine) block histamine H2 receptors on parietal cells, reducing cAMP-mediated acid secretion by approximately 70%. They are effective at suppressing fasting and nocturnal acid secretion. However, PPIs are more effective overall because they block the final common pathway (the proton pump) regardless of the stimulus (histamine, gastrin, or acetylcholine).','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antacids & PPIs','hard','mcq','A patient with renal impairment is prescribed antacids. Which antacid component is most likely to accumulate and cause toxicity in this patient?','["A. Sodium bicarbonate causing hypokalaemia","B. Magnesium salts causing hypermagnesaemia","C. Calcium carbonate causing hypocalcaemia","D. Alginic acid causing respiratory depression"]','B','In patients with renal impairment, magnesium-containing antacids (e.g., magnesium trisilicate, magnesium hydroxide) can cause hypermagnesaemia because the kidney is the primary route of magnesium excretion. Hypermagnesaemia can cause muscle weakness, hypotension, respiratory depression, and cardiac arrhythmias. Aluminium-containing antacids can also accumulate causing aluminium toxicity (encephalopathy, bone disease).','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

-- SUBTOPIC 2: H. pylori Eradication (10 MCQs)
('{"medicine"}','Medicine','Gastroenterology','Pharmacology','H. pylori Eradication','easy','mcq','What is the Ghana STG 2017 recommended first-line triple therapy for H. pylori eradication?','["A. Omeprazole + clarithromycin + metronidazole for 7 days","B. Ranitidine + amoxicillin + metronidazole for 14 days","C. Omeprazole 20mg BD + amoxicillin 1g BD + clarithromycin 500mg BD for 7–14 days","D. Bismuth subcitrate + tetracycline + metronidazole for 10 days"]','C','According to the Ghana STG 2017, first-line H. pylori eradication uses triple therapy: omeprazole 20mg twice daily + amoxicillin 1g twice daily + clarithromycin 500mg twice daily for 7–14 days. The PPI reduces gastric acid, improving antibiotic stability and efficacy, while the two antibiotics target H. pylori directly. Eradication rates with this regimen exceed 85% in areas without clarithromycin resistance.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','H. pylori Eradication','medium','mcq','A patient requiring H. pylori eradication reports a penicillin allergy. What modification to the standard triple therapy regimen is recommended?','["A. Replace clarithromycin with tetracycline","B. Use levofloxacin instead of both antibiotics","C. Replace omeprazole with ranitidine","D. Replace amoxicillin with metronidazole 400mg BD"]','D','In patients with penicillin allergy, amoxicillin is substituted with metronidazole 400mg twice daily. The resulting regimen is: omeprazole 20mg BD + metronidazole 400mg BD + clarithromycin 500mg BD for 7–14 days. This is recommended in the Ghana STG 2017 as the alternative first-line regimen for penicillin-allergic patients.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','H. pylori Eradication','medium','mcq','What is the recommended test to confirm H. pylori eradication after completing therapy?','["A. Urea breath test or stool antigen test at least 4 weeks after completing therapy","B. Endoscopy with CLO test immediately after treatment","C. Serology (IgG antibody titre) 2 weeks after treatment","D. H. pylori culture from stool at 2 weeks post-treatment"]','A','The urea breath test (UBT) and stool antigen test (SAT) are the preferred non-invasive tests for confirming H. pylori eradication. They should be performed at least 4 weeks after completing antibiotic therapy and at least 2 weeks after stopping PPIs to avoid false-negative results. Serology is NOT used for test of cure because antibody titres remain elevated for months after successful eradication.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','H. pylori Eradication','hard','mcq','What is the composition of quadruple therapy for H. pylori eradication when clarithromycin resistance is suspected?','["A. PPI + amoxicillin + clarithromycin + metronidazole for 14 days","B. PPI + bismuth subcitrate + metronidazole + tetracycline for 14 days","C. PPI + rifaximin + metronidazole + amoxicillin for 10 days","D. PPI + levofloxacin + amoxicillin + bismuth for 7 days"]','B','Bismuth quadruple therapy is used when clarithromycin resistance is suspected or first-line triple therapy has failed. It consists of: PPI (standard dose BD) + bismuth subcitrate 120mg QDS + metronidazole 400mg TDS + tetracycline 500mg QDS for 14 days. Bismuth directly kills H. pylori by disrupting its cell wall. This regimen achieves eradication rates of >90% regardless of clarithromycin resistance status.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','H. pylori Eradication','easy','mcq','What additional role does bismuth subcitrate play beyond its antibiotic synergism in H. pylori quadruple therapy?','["A. Irreversible inhibition of H+/K+ ATPase on parietal cells","B. Stimulation of prostaglandin synthesis in gastric mucosa","C. Direct bactericidal effect on H. pylori by disrupting its cell wall and enzyme function","D. Competitive antagonism of H2 receptors on parietal cells"]','C','Bismuth subcitrate has direct bactericidal activity against H. pylori. It disrupts the bacterial cell wall integrity, inhibits urease and other H. pylori enzymes, and prevents bacterial adhesion to the gastric epithelium. It also has a mild antacid effect and can be used for traveller''s diarrhoea. It does not inhibit the proton pump or H2 receptors.','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','H. pylori Eradication','medium','mcq','Why is a PPI included in H. pylori eradication regimens?','["A. PPIs directly inhibit H. pylori urease enzyme","B. PPIs create an alkaline environment that enhances H. pylori growth for antibiotic targeting","C. PPIs stimulate gastric acid secretion to activate pro-antibiotics","D. PPIs raise intragastric pH, improving antibiotic stability and activity against H. pylori"]','D','H. pylori eradication antibiotics (particularly clarithromycin and amoxicillin) are significantly more stable and effective at higher intragastric pH. PPIs raise intragastric pH above 6, which dramatically improves antibiotic efficacy against H. pylori. Additionally, H. pylori is most susceptible to antibiotics in its replicating state, which occurs more at higher pH. This explains why PPI dose and compliance directly impacts eradication success rates.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','H. pylori Eradication','hard','mcq','A patient fails first-line triple therapy with omeprazole, amoxicillin, and clarithromycin. Clarithromycin resistance is confirmed. Which second-line regimen is most appropriate?','["A. Bismuth quadruple therapy (PPI + bismuth + metronidazole + tetracycline) for 14 days","B. Switch to levofloxacin-based triple therapy (PPI + levofloxacin + amoxicillin)","C. Repeat the same triple therapy at higher doses for 14 days","D. Single-agent therapy with high-dose metronidazole"]','A','Following failure of clarithromycin-based triple therapy, bismuth quadruple therapy is the preferred salvage regimen. It does not contain clarithromycin and achieves high eradication rates (>90%) even when clarithromycin resistance is present. Levofloxacin-based therapy is an alternative second-line option but carries its own resistance concerns. Repeating a failed regimen is never appropriate.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','H. pylori Eradication','medium','mcq','Which statement about H. pylori and its relationship to peptic ulcer disease is most accurate?','["A. H. pylori is found in <20% of duodenal ulcer patients","B. H. pylori eradication dramatically reduces duodenal ulcer recurrence from ~80% to <5% per year","C. H. pylori eradication has no impact on ulcer recurrence rates","D. H. pylori only causes gastric ulcers, not duodenal ulcers"]','B','H. pylori is found in approximately 95% of duodenal ulcers and 70% of gastric ulcers. Without eradication, ulcer recurrence rates are approximately 80% per year. Successful H. pylori eradication reduces recurrence to less than 5% per year, effectively curing the underlying cause. This represents one of the most cost-effective interventions in gastroenterology.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','H. pylori Eradication','easy','mcq','For how long is standard first-line triple therapy for H. pylori typically prescribed according to Ghana STG 2017?','["A. 3–5 days","B. 21 days","C. 7–14 days","D. 4–6 weeks"]','C','The Ghana STG 2017 recommends first-line triple therapy for 7–14 days. Seven-day regimens are adequate in regions with low clarithromycin resistance, while 14-day courses are preferred where resistance rates are higher (>15–20%). Longer duration generally improves eradication rates by approximately 5%. Patient compliance is critical, and the full course must be completed even if symptoms resolve earlier.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','H. pylori Eradication','hard','mcq','Why should PPIs be stopped at least 2 weeks before performing a urea breath test for H. pylori?','["A. PPIs induce antibody production that can cause false-positive results","B. PPIs accelerate gastric emptying, invalidating test results","C. PPIs react with the urea tracer causing spurious CO2 measurements","D. PPIs suppress H. pylori activity, reducing urease production and causing false-negative results"]','D','PPIs suppress H. pylori urease activity and reduce bacterial load without eliminating the organism. Since the urea breath test relies on H. pylori urease to cleave radiolabelled urea and produce labelled CO2, PPI-mediated urease suppression leads to false-negative results. PPIs should be stopped for at least 2 weeks before UBT. Similarly, antibiotics should be stopped for 4 weeks before testing.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

-- SUBTOPIC 3: Antiemetics (10 MCQs)
('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antiemetics','easy','mcq','Which antiemetic drug is a 5-HT3 receptor antagonist and is most effective for chemotherapy-induced nausea and vomiting?','["A. Ondansetron","B. Prochlorperazine","C. Metoclopramide","D. Domperidone"]','A','Ondansetron is a selective 5-HT3 receptor antagonist. It blocks serotonin receptors in the chemoreceptor trigger zone (CTZ), nucleus tractus solitarius, and peripheral vagal afferents in the gut. It is highly effective for chemotherapy-induced and post-operative nausea and vomiting. Unlike dopamine antagonists, ondansetron does not cause extrapyramidal side effects, making it safer for patients at risk of movement disorders.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antiemetics','medium','mcq','A young woman is given metoclopramide for nausea. She develops involuntary repetitive movements of her face and neck after several days. What is the most likely mechanism?','["A. Blockade of muscarinic receptors in the basal ganglia","B. Blockade of central dopamine D2 receptors causing extrapyramidal effects","C. Stimulation of 5-HT4 receptors in the enteric nervous system","D. Histamine H1 receptor antagonism in the cerebellum"]','B','Metoclopramide is a D2 receptor antagonist that crosses the blood-brain barrier. Central dopamine D2 blockade in the basal ganglia (nigrostriatal pathway) causes extrapyramidal side effects including akathisia (restlessness), dystonia (involuntary muscle contractions), parkinsonism, and with prolonged use, tardive dyskinesia. These effects are more common in young women and children. Its prokinetic action is mediated by D2 antagonism and 5-HT4 agonism in the enteric nervous system.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antiemetics','medium','mcq','What is the key pharmacological difference between domperidone and metoclopramide as antiemetics?','["A. Domperidone blocks 5-HT3 receptors while metoclopramide blocks D2 receptors","B. Metoclopramide prolongs the QT interval while domperidone does not","C. Domperidone does not cross the blood-brain barrier and therefore causes fewer extrapyramidal effects","D. Domperidone is only effective for post-operative nausea while metoclopramide is used for chemotherapy"]','C','Both domperidone and metoclopramide are D2 receptor antagonists. The critical difference is that domperidone does not cross the blood-brain barrier (due to its high molecular weight and polarity), so it acts only on peripheral D2 receptors (in the gut and at the CTZ in the area postrema, which lies outside the BBB). This makes domperidone significantly less likely to cause extrapyramidal effects. However, domperidone is associated with QT interval prolongation and cardiac arrhythmias.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antiemetics','easy','mcq','Which antiemetic is most appropriate for motion sickness?','["A. Ondansetron","B. Metoclopramide","C. Prochlorperazine","D. Hyoscine (scopolamine)"]','D','Hyoscine (scopolamine) is an anticholinergic (muscarinic antagonist) that acts on the vestibular nucleus and vomiting centre to prevent motion-induced nausea. It is available as a transdermal patch, oral tablets, or injection. For motion sickness, it is more effective than antihistamines and far more effective than ondansetron (which works mainly via the CTZ and gut 5-HT3 receptors). Side effects include dry mouth, blurred vision, and sedation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antiemetics','hard','mcq','The chemoreceptor trigger zone (CTZ) is particularly sensitive to blood-borne emetic stimuli because of its unique anatomical feature. What is this feature?','["A. It is located in the area postrema, which lies outside the blood-brain barrier","B. It has a dense blood supply from the portal circulation only","C. It expresses uniquely high levels of acetylcholinesterase","D. It is directly connected to the vagus nerve without any synaptic relay"]','A','The chemoreceptor trigger zone (CTZ) is located in the area postrema on the floor of the fourth ventricle. Unlike most brain regions, the area postrema lacks a normal blood-brain barrier, allowing it to directly sample blood and cerebrospinal fluid for emetic stimuli (drugs, toxins, metabolic disturbances). This is why drugs that do not cross the BBB (e.g., domperidone, apomorphine) can still activate the CTZ and trigger vomiting or, conversely, why D2 antagonists like domperidone can suppress CTZ-mediated nausea.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antiemetics','medium','mcq','Prochlorperazine is used as an antiemetic. What is the most serious adverse effect associated with its long-term use?','["A. Peptic ulcer disease due to increased acid secretion","B. Tardive dyskinesia due to chronic dopamine D2 receptor blockade","C. Agranulocytosis requiring regular blood count monitoring","D. Serotonin syndrome when combined with SSRIs"]','B','Prochlorperazine is a phenothiazine antipsychotic used as an antiemetic via D2 receptor blockade in the CTZ. Long-term or high-dose use causes tardive dyskinesia — irreversible, repetitive involuntary movements (lip-smacking, grimacing, tongue protrusion) resulting from dopamine receptor upregulation and supersensitivity after prolonged blockade. Acute extrapyramidal effects (dystonia, akathisia) are also common. It should not be used long-term as an antiemetic.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antiemetics','easy','mcq','Cyclizine is an antihistamine antiemetic. What is its primary mechanism of action?','["A. Serotonin 5-HT3 receptor antagonism in the nucleus tractus solitarius","B. Dopamine D2 receptor antagonism in the chemoreceptor trigger zone","C. Histamine H1 receptor antagonism in the vomiting centre and vestibular pathways","D. Muscarinic receptor stimulation increasing gastric motility"]','C','Cyclizine is an H1 antihistamine that acts on histamine H1 receptors in the vomiting centre (nucleus tractus solitarius) and vestibular pathways. It is effective for motion sickness, labyrinthitis, and opioid-induced nausea (opioids stimulate vestibular pathways). It also has some anticholinergic activity. Common side effects include sedation and dry mouth. It is a component of combined antiemetic formulations.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antiemetics','hard','mcq','A patient undergoing highly emetogenic chemotherapy (cisplatin-based) requires the most effective antiemetic prophylaxis. Which combination is most appropriate for acute chemotherapy-induced nausea and vomiting?','["A. Cyclizine + prochlorperazine + hyoscine","B. Ondansetron alone at maximum dose","C. Metoclopramide + domperidone + lorazepam","D. Ondansetron + dexamethasone + NK1 receptor antagonist (aprepitant)"]','D','For highly emetogenic chemotherapy (HEC), the standard of care is triple antiemetic prophylaxis: a 5-HT3 antagonist (ondansetron/granisetron) + corticosteroid (dexamethasone) + NK1 receptor antagonist (aprepitant/fosaprepitant). NK1 antagonists block substance P binding to NK1 receptors in the vomiting centre, particularly effective for delayed CINV (24–120 hours post-chemotherapy). Dexamethasone''s antiemetic mechanism is not fully understood but may involve prostaglandin inhibition and 5-HT3 receptor modulation.','universal',true,'{year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antiemetics','medium','mcq','Metoclopramide has prokinetic properties in addition to antiemetic effects. Which receptor mechanism mediates its prokinetic action?','["A. D2 receptor antagonism and 5-HT4 receptor agonism in the enteric nervous system","B. D2 receptor agonism increasing lower oesophageal sphincter tone only","C. 5-HT3 receptor agonism in the colon","D. Motilin receptor agonism increasing propulsive peristalsis"]','A','Metoclopramide''s prokinetic effect is mediated by both D2 receptor antagonism (relieving dopamine-mediated inhibition of gut motility) and 5-HT4 receptor agonism (directly stimulating propulsive motility in the upper GI tract). Together, these increase lower oesophageal sphincter tone, accelerate gastric emptying, and enhance duodenal motility. This makes metoclopramide useful in gastroparesis and GORD in addition to nausea.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antiemetics','medium','mcq','Which antiemetic mechanism best explains why dexamethasone is used in chemotherapy-induced nausea?','["A. Direct 5-HT3 receptor antagonism in the nucleus tractus solitarius","B. Glucocorticoid-mediated reduction of prostaglandins and possible 5-HT3 receptor modulation","C. Central dopamine D2 receptor blockade in the CTZ","D. NK1 receptor antagonism blocking substance P signalling"]','B','Dexamethasone''s antiemetic mechanism is not completely understood. It is thought to involve inhibition of prostaglandin synthesis (via phospholipase A2 inhibition), possible modulation of 5-HT3 receptor expression, and reduction of BBB permeability to emetic stimuli. It is effective both for acute CINV (within 24 hours) and delayed CINV, and is synergistic with 5-HT3 antagonists. It is often given as a single dose before chemotherapy.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

-- SUBTOPIC 4: Laxatives & Antidiarrhoeals (10 MCQs)
('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Laxatives & Antidiarrhoeals','easy','mcq','Loperamide is used to treat non-specific diarrhoea. What is its primary mechanism of action?','["A. 5-HT3 receptor antagonism reducing gut secretion","B. Osmotic effect increasing water in the gut lumen","C. Mu-opioid receptor agonism in the gut wall, reducing peristalsis and increasing sphincter tone","D. Direct antimicrobial activity against enteric pathogens"]','C','Loperamide is a synthetic opioid that acts on mu-opioid receptors in the myenteric plexus of the gut wall. It reduces peristalsis, increases ileocaecal and anal sphincter tone, and decreases intestinal secretion, resulting in slower gut transit and firmer stools. Critically, loperamide does not cross the blood-brain barrier (due to P-glycoprotein efflux), so it has no CNS opioid effects (no analgesia or euphoria). Usual adult dose is 4mg initially, then 2mg after each loose stool (max 16mg/day).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Laxatives & Antidiarrhoeals','medium','mcq','In which of the following clinical situations is loperamide CONTRAINDICATED?','["A. Traveller''s diarrhoea without blood in stool","B. Post-operative ileus prevention","C. IBS-predominant diarrhoea","D. Bloody diarrhoea (dysentery) and Clostridioides difficile infection"]','D','Loperamide is contraindicated in bloody diarrhoea (dysentery caused by organisms like Shigella, EHEC, Salmonella) and Clostridioides difficile infection. In these conditions, reducing gut motility prolongs contact time with toxin-producing organisms or invasive bacteria, potentially worsening the infection, increasing toxin absorption, and risking toxic megacolon (particularly in C. difficile). In dysentery, antiperistaltic drugs are contraindicated as they delay pathogen clearance.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Laxatives & Antidiarrhoeals','easy','mcq','What are the components of the WHO/Ghana STG oral rehydration solution (ORS) per litre of water?','["A. Sodium chloride 3.5g, sodium citrate 2.9g, potassium chloride 1.5g, glucose 20g","B. Sodium chloride 3.5g, sodium bicarbonate 2.5g, potassium chloride 1.5g, glucose 20g","C. Sodium chloride 5g, potassium chloride 2g, glucose 20g, calcium gluconate 1g","D. Sodium chloride 3g, sodium citrate 2.9g, glucose 25g, zinc sulphate 20mg"]','A','The standard WHO ORS (as referenced in Ghana STG) contains per litre of clean water: sodium chloride 3.5g (sodium), sodium citrate 2.9g (base to correct acidosis), potassium chloride 1.5g (replace potassium losses), and glucose 20g (glucose-sodium co-transport drives fluid absorption). This replaces the older sodium bicarbonate formula. Zinc supplementation (10–20mg daily for 10–14 days) is recommended adjunctively in children with diarrhoea.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Laxatives & Antidiarrhoeals','medium','mcq','Which type of laxative is MOST appropriate as a first-line treatment for chronic constipation in a patient who does not drink adequate fluids?','["A. Bulk-forming laxatives (ispaghula/psyllium)","B. Osmotic laxatives (macrogol/polyethylene glycol)","C. Stimulant laxatives (senna)","D. Stool softeners (docusate sodium)"]','B','Bulk-forming laxatives (ispaghula, methylcellulose) require adequate fluid intake (at least 6–8 glasses daily) to be effective and safe — insufficient fluid can paradoxically worsen constipation or cause intestinal obstruction. For patients unable to maintain adequate fluid intake, osmotic laxatives such as macrogol (polyethylene glycol) or lactulose are preferred as they draw water into the colon independently. Macrogol is generally better tolerated than lactulose (less bloating/gas).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Laxatives & Antidiarrhoeals','hard','mcq','Why does lactulose cause abdominal bloating and flatulence despite being effective as a laxative?','["A. Lactulose directly stimulates colonic smooth muscle causing spasm","B. Lactulose inhibits intestinal bicarbonate secretion causing acid build-up","C. Colonic bacteria ferment lactulose producing hydrogen, methane, and CO2 gases","D. Lactulose induces prostaglandin release causing gut wall inflammation"]','C','Lactulose is a non-absorbable disaccharide that is not hydrolysed by intestinal enzymes. When it reaches the colon, bacterial fermentation converts it to short-chain fatty acids (acidifying the colon) and gas (hydrogen, methane, CO2). This gas production causes the characteristic bloating, flatulence, and abdominal cramping associated with lactulose. Despite these side effects, the acidification is therapeutically useful in hepatic encephalopathy (converting NH3 to NH4+, trapping it in the colon).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Laxatives & Antidiarrhoeals','medium','mcq','Stimulant laxatives such as senna act by which mechanism?','["A. Increasing stool bulk through hydrophilic polysaccharides","B. Drawing water into the colon via osmotic gradient","C. Inhibiting sodium absorption in the colonic epithelium via direct epithelial contact","D. Stimulating myenteric nerve plexus causing increased peristalsis and fluid secretion"]','D','Senna (and bisacodyl) are stimulant laxatives that are converted by colonic bacteria to active compounds (anthraquinones from senna, or directly irritate the mucosa as bisacodyl). They stimulate the myenteric nerve plexus, increasing propulsive peristalsis and promoting electrolyte and water secretion into the colon lumen. They are fast-acting (6–12 hours for senna, 6–10 hours for bisacodyl). Long-term use can cause electrolyte imbalances (hypokalaemia) and melanosis coli.','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Laxatives & Antidiarrhoeals','easy','mcq','Docusate sodium is classified as which type of laxative?','["A. Faecal softener (surfactant laxative)","B. Stimulant laxative","C. Bulk-forming laxative","D. Osmotic laxative"]','A','Docusate sodium is a faecal softener (emollient/surfactant laxative). It acts like a detergent by reducing surface tension and allowing water and fats to penetrate hardened stool, softening it. It is the mildest laxative and is particularly useful for patients who should avoid straining (post-myocardial infarction, post-surgical, haemorrhoids). It has minimal systemic effects. It takes 1–3 days to work and is not effective for acute constipation.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Laxatives & Antidiarrhoeals','hard','mcq','A patient with chronic renal failure develops constipation. Which laxative should be avoided and why?','["A. Lactulose — risk of metabolic alkalosis","B. Magnesium salts (osmotic laxatives) — risk of hypermagnesaemia","C. Macrogol — risk of fluid overload","D. Ispaghula — risk of intestinal obstruction in all renal patients"]','B','In chronic renal failure, magnesium-containing laxatives (e.g., magnesium hydroxide, magnesium sulphate) should be avoided because the impaired kidney cannot adequately excrete absorbed magnesium, leading to hypermagnesaemia. This can cause hypotension, bradycardia, respiratory depression, muscle paralysis, and cardiac arrest. Safe alternatives in renal failure include lactulose, macrogol (with care regarding fluid balance), and stimulant laxatives like senna.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Laxatives & Antidiarrhoeals','medium','mcq','Macrogol (polyethylene glycol) works as a laxative by which mechanism?','["A. Fermentation by colonic bacteria producing osmotically active particles","B. Stimulating secretin release from the small intestinal mucosa","C. Remaining unabsorbed in the gut lumen and retaining water through hydrogen bonding","D. Inhibiting aquaporins in the colonic epithelium"]','C','Macrogol (PEG) is an inert, high-molecular-weight polymer that is neither absorbed nor metabolised. It retains water molecules through hydrogen bonding within the gut lumen, increasing stool volume and softness. Unlike lactulose, it does not undergo bacterial fermentation, so it causes less bloating and gas. It is effective for constipation and faecal impaction and is considered the first-line osmotic laxative in many guidelines.','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Laxatives & Antidiarrhoeals','hard','mcq','A child presents with severe acute gastroenteritis and signs of dehydration. Which is the MOST important initial pharmacological intervention?','["A. Loperamide to slow gut motility and reduce fluid loss","B. Ondansetron to control vomiting before fluid replacement","C. Metronidazole empirically for presumed bacterial infection","D. Oral rehydration solution to replace fluid and electrolytes"]','D','The cornerstone of management for acute gastroenteritis with dehydration — regardless of cause — is oral rehydration with ORS. ORS exploits the intact glucose-sodium co-transport mechanism (SGLT1) in the intestinal epithelium, which remains functional even in secretory diarrhoea. Loperamide is contraindicated in children under 12 and in bloody/infective diarrhoea. Antibiotics are only indicated for specific bacterial causes. ORS has reduced global child mortality from diarrhoea dramatically.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),

-- SUBTOPIC 5: IBD Pharmacotherapy (10 MCQs)
('{"medicine"}','Medicine','Gastroenterology','Pharmacology','IBD Pharmacotherapy','easy','mcq','Which drug class is used as first-line therapy for mild to moderate ulcerative colitis?','["A. 5-aminosalicylates (mesalazine, sulfasalazine)","B. Anti-TNF biologics (infliximab)","C. Systemic corticosteroids (prednisolone)","D. Azathioprine as monotherapy"]','A','5-aminosalicylates (5-ASA) such as mesalazine (mesalamine) and sulfasalazine are first-line for inducing and maintaining remission in mild to moderate ulcerative colitis. They act topically on the colonic mucosa, reducing inflammation through multiple mechanisms including inhibition of prostaglandin synthesis and NF-kB signalling. Rectal formulations are preferred for proctitis/distal UC. Sulfasalazine is a prodrug split by colonic bacteria into sulfapyridine and the active mesalazine moiety.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','IBD Pharmacotherapy','medium','mcq','A male patient on sulfasalazine for ulcerative colitis reports infertility. What is the mechanism of this adverse effect?','["A. Sulfapyridine causes seminiferous tubule fibrosis","B. Sulfasalazine causes reversible oligospermia and abnormal sperm motility","C. Sulfasalazine induces testosterone deficiency by CYP3A4 inhibition","D. Mesalazine moiety causes permanent spermatogenesis arrest"]','B','Sulfasalazine causes reversible male infertility through oligospermia (reduced sperm count) and abnormal sperm morphology and motility. This effect is attributed to the sulfapyridine component. The infertility resolves within 2–3 months of stopping sulfasalazine and can be managed by switching to mesalazine (the active component alone, without sulfapyridine). Sulfasalazine also inhibits folate absorption, and supplementation with folic acid is recommended.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','IBD Pharmacotherapy','hard','mcq','Before starting azathioprine for IBD, why is it important to check thiopurine methyltransferase (TPMT) activity?','["A. High TPMT activity causes rapid conversion to toxic oxypurine metabolites causing nephrotoxicity","B. TPMT activity determines the oral bioavailability of azathioprine","C. Low or absent TPMT activity leads to accumulation of cytotoxic thioguanine nucleotides causing severe bone marrow suppression","D. TPMT converts azathioprine to 6-mercaptopurine, and reduced activity means no therapeutic effect"]','C','Azathioprine is a prodrug metabolised to 6-mercaptopurine (6-MP), which is then metabolised via three competing pathways. TPMT converts 6-MP to inactive 6-methylmercaptopurine. In patients with low or absent TPMT activity (10% heterozygous, 0.3% homozygous), 6-MP is preferentially shunted towards toxic 6-thioguanine nucleotides (6-TGN), causing severe bone marrow suppression (leucopenia, thrombocytopenia). Checking TPMT before starting azathioprine allows dose adjustment or drug avoidance.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','IBD Pharmacotherapy','medium','mcq','Infliximab is used in moderate-to-severe Crohn''s disease refractory to steroids and immunomodulators. What is its mechanism of action?','["A. Inhibition of interleukin-6 (IL-6) receptor signalling","B. Inhibition of IL-12 and IL-23 reducing Th17 cell activation","C. Blockade of alpha-4 integrin preventing leucocyte migration into the gut","D. Monoclonal antibody binding to and neutralising tumour necrosis factor-alpha (TNF-α)"]','D','Infliximab is a chimeric (mouse-human) monoclonal antibody (IgG1) that binds to both soluble and membrane-bound TNF-α, neutralising its pro-inflammatory effects. TNF-α is a key cytokine driving intestinal inflammation in IBD. By blocking TNF-α, infliximab reduces mucosal inflammation, promotes mucosal healing, and can close fistulae. It is given intravenously and requires screening for tuberculosis and hepatitis B before initiation.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','IBD Pharmacotherapy','easy','mcq','Budesonide is preferred over systemic prednisolone for mild-to-moderate Crohn''s ileitis. What pharmacological property explains this preference?','["A. Budesonide undergoes extensive first-pass hepatic metabolism, reducing systemic exposure and side effects","B. Budesonide has greater systemic anti-inflammatory potency than prednisolone","C. Budesonide selectively inhibits TNF-α production only in the ileum","D. Budesonide is not absorbed from the gastrointestinal tract at all"]','A','Budesonide is a locally acting corticosteroid formulated as extended-release capsules that deliver drug to the terminal ileum and ascending colon. It has high topical anti-inflammatory potency, but undergoes extensive first-pass metabolism in the liver (>90%), so systemic bioavailability is only ~10%. This greatly reduces systemic corticosteroid side effects (adrenal suppression, osteoporosis, hyperglycaemia, Cushingoid features) compared to prednisolone, while maintaining local efficacy.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','IBD Pharmacotherapy','hard','mcq','Vedolizumab is approved for IBD. What is its mechanism of action and why is it considered gut-selective?','["A. It blocks IL-12/23 systemically, preventing Th1 and Th17 cell differentiation throughout the body","B. It inhibits alpha-4 beta-7 integrin, selectively preventing lymphocyte trafficking to the gut","C. It depletes B lymphocytes by binding CD20 on their surface","D. It inhibits JAK1/JAK3 signalling downstream of multiple cytokine receptors"]','B','Vedolizumab is a humanised monoclonal antibody that selectively blocks the α4β7 integrin on gut-homing lymphocytes. α4β7 binds to MAdCAM-1 (mucosal addressin cell adhesion molecule-1), which is specifically expressed on gut-associated vascular endothelium. By blocking this interaction, vedolizumab prevents lymphocyte migration into the intestinal mucosa. Unlike natalizumab (anti-α4 integrin), vedolizumab does not affect brain lymphocyte trafficking, giving it gut-selectivity and avoiding the risk of PML (progressive multifocal leukoencephalopathy).','universal',true,'{year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','IBD Pharmacotherapy','medium','mcq','Which biological agent targets IL-12 and IL-23 and is approved for Crohn''s disease?','["A. Infliximab","B. Adalimumab","C. Ustekinumab","D. Vedolizumab"]','C','Ustekinumab is a fully human monoclonal antibody that binds to the p40 subunit shared by IL-12 and IL-23, blocking both cytokines. IL-12 drives Th1 cell differentiation and interferon-gamma production; IL-23 drives Th17 cell differentiation and IL-17 production. Both pathways are implicated in Crohn''s disease pathogenesis. Ustekinumab is approved for moderate-to-severe Crohn''s disease and ulcerative colitis in patients who have failed anti-TNF therapy.','universal',true,'{year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','IBD Pharmacotherapy','medium','mcq','What is the most important pre-treatment screening step before starting anti-TNF therapy (infliximab/adalimumab) for IBD?','["A. TPMT genotyping to predict bone marrow suppression","B. Echocardiogram to exclude cardiac contraindications","C. Colonoscopy to confirm disease extent before first infusion","D. Tuberculosis screening (IGRA or Mantoux test) and hepatitis B serology"]','D','Anti-TNF agents suppress immune function and can reactivate latent tuberculosis (TB) or chronic hepatitis B. All patients must be screened for latent TB with an interferon-gamma release assay (IGRA, e.g., QuantiFERON) or Mantoux test and chest X-ray before starting anti-TNF therapy. Latent TB must be treated with prophylactic isoniazid for 6–9 months before initiating anti-TNF. Hepatitis B serology (HBsAg, anti-HBc) is also essential. HIV testing and appropriate vaccinations should be considered.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','IBD Pharmacotherapy','easy','mcq','Sulfasalazine is a prodrug. What are the active components produced when it is split by colonic bacteria?','["A. Mesalazine (5-aminosalicylic acid) and sulfapyridine","B. Salicylic acid and sulfamethoxazole","C. Methotrexate and sulfapyridine","D. Balsalazide and mesalazine"]','A','Sulfasalazine is a prodrug consisting of mesalazine (5-ASA) linked to sulfapyridine by an azo bond. Colonic bacteria cleave this azo bond, releasing mesalazine (the therapeutically active anti-inflammatory component) locally in the colon and sulfapyridine (which is absorbed and responsible for most of the systemic side effects: nausea, headache, haemolytic anaemia, oligospermia, and folate deficiency). Newer 5-ASA drugs (mesalazine alone) avoid the sulfapyridine-related side effects.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','IBD Pharmacotherapy','hard','mcq','A patient with UC is maintained on azathioprine. The physician wants to add allopurinol for gout. Why is this combination potentially dangerous?','["A. Allopurinol induces azathioprine metabolism, reducing its efficacy","B. Allopurinol inhibits xanthine oxidase, blocking 6-MP inactivation and causing marked azathioprine toxicity","C. Both drugs compete for renal tubular secretion, causing allopurinol accumulation","D. Allopurinol displaces azathioprine from albumin binding sites increasing free drug levels"]','B','Allopurinol inhibits xanthine oxidase (XO), one of three competing enzymes that metabolise 6-mercaptopurine (the active metabolite of azathioprine). Blocking XO shunts 6-MP metabolism toward the 6-thioguanine nucleotide (6-TGN) pathway, dramatically increasing cytotoxic 6-TGN levels. This causes severe, potentially life-threatening bone marrow suppression (leucopenia, pancytopenia). If the combination is unavoidable, azathioprine dose must be reduced by 75% and blood counts monitored closely.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

-- SUBTOPIC 6: Antispasmodics & Prokinetics (10 MCQs)
('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antispasmodics & Prokinetics','easy','mcq','Hyoscine butylbromide (Buscopan) is used in irritable bowel syndrome. What is its mechanism of action?','["A. Dopamine D2 receptor antagonism reducing colonic spasm","B. 5-HT4 agonism increasing propulsive motility","C. Muscarinic receptor antagonism relaxing smooth muscle in the GI tract","D. Alpha-2 adrenoceptor agonism reducing gut secretion"]','C','Hyoscine butylbromide is a quaternary ammonium anticholinergic compound that blocks muscarinic (M3) receptors on gastrointestinal smooth muscle. This produces smooth muscle relaxation, reducing painful colonic spasms in IBS and other functional GI disorders. Because it is quaternary (charged), it does not cross the blood-brain barrier and therefore has fewer CNS effects than tertiary anticholinergics. It is also used to relieve ureteric and biliary colic.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antispasmodics & Prokinetics','medium','mcq','Mebeverine is used as an antispasmodic for IBS. How does it differ from hyoscine butylbromide?','["A. Mebeverine blocks H1 receptors while hyoscine blocks muscarinic receptors","B. Mebeverine blocks calcium channels in the colon via an L-type mechanism","C. Mebeverine is a prokinetic while hyoscine butylbromide reduces gut motility","D. Mebeverine acts directly on intestinal smooth muscle to reduce spasm, without anticholinergic effects"]','D','Mebeverine is a direct-acting smooth muscle relaxant (musculotropic antispasmodic) that acts directly on intestinal smooth muscle, independent of autonomic innervation. Unlike hyoscine, it has no anticholinergic side effects (no dry mouth, blurred vision, urinary retention, constipation). It is therefore better tolerated for long-term use in IBS. Its exact mechanism involves stabilising smooth muscle cell membranes and possibly blocking calcium influx.','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antispasmodics & Prokinetics','medium','mcq','Erythromycin is sometimes used as a prokinetic at low doses. What receptor does it act on to stimulate GI motility?','["A. Motilin receptors in the upper gastrointestinal tract","B. 5-HT4 receptors in the enteric nervous system","C. Dopamine D2 receptors in the stomach","D. Muscarinic M3 receptors on smooth muscle"]','A','At low, sub-antimicrobial doses, erythromycin acts as a motilin receptor agonist. Motilin is an endogenous peptide hormone released from the duodenum that triggers the migrating motor complex (MMC) — the interdigestive housekeeping contractions. Erythromycin mimics motilin, stimulating powerful gastric contractions and accelerating gastric emptying. It is used in gastroparesis, particularly when other prokinetics fail. Tachyphylaxis can develop with prolonged use.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antispasmodics & Prokinetics','easy','mcq','Which of the following prokinetics is most appropriate for a patient with gastroparesis who has a history of Parkinson''s disease?','["A. Metoclopramide — D2 antagonist with good central safety profile","B. Domperidone — D2 antagonist that does not cross the blood-brain barrier","C. Prochlorperazine — phenothiazine D2 antagonist with prokinetic properties","D. Erythromycin — motilin agonist that worsens tremor in Parkinson''s disease"]','B','In a patient with Parkinson''s disease, dopamine D2 receptor function is critical. Metoclopramide and prochlorperazine cross the BBB and block central D2 receptors, worsening Parkinson''s symptoms (tremor, rigidity, bradykinesia) and are absolutely contraindicated in this condition. Domperidone does not cross the BBB, so it acts only peripherally and in the area postrema (outside BBB), making it the prokinetic of choice in Parkinson''s patients. However, cardiac monitoring for QT prolongation is needed.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antispasmodics & Prokinetics','hard','mcq','Prucalopride is used for chronic constipation. What is its mechanism of action and where does it act?','["A. Inhibits colonic sodium/hydrogen exchange, increasing intraluminal fluid","B. Opioid mu receptor antagonist reversing constipation caused by opioid drugs","C. Selective high-affinity 5-HT4 agonist in the colon, stimulating propulsive peristalsis","D. Chloride channel activator (CaCC) increasing colonic secretion"]','C','Prucalopride is a highly selective, high-affinity 5-HT4 receptor agonist. 5-HT4 receptor activation in the colon (particularly the ascending colon) enhances the release of acetylcholine and calcitonin gene-related peptide from enteric neurons, stimulating propulsive peristalsis. Unlike the older prokinetics (e.g., cisapride, tegaserod) which had cardiovascular risks, prucalopride is selective for 5-HT4 receptors with minimal affinity for cardiac hERG channels and a good safety profile.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antispasmodics & Prokinetics','medium','mcq','Domperidone is associated with which serious cardiac side effect that has led to restrictions on its use?','["A. Bradycardia and complete heart block","B. Hypertension due to peripheral dopamine receptor blockade","C. Atrial fibrillation mediated by vagal stimulation","D. QT interval prolongation and risk of ventricular arrhythmias (Torsades de pointes)"]','D','Domperidone prolongs the cardiac QT interval by blocking hERG potassium channels in cardiac myocytes, similar to other dopamine antagonists. Prolonged QT can lead to Torsades de pointes (a potentially fatal polymorphic ventricular tachycardia) and sudden cardiac death. This risk led to regulatory restrictions: domperidone should be used at the lowest effective dose, for the shortest duration, avoided in patients with pre-existing QT prolongation, and not combined with other QT-prolonging drugs.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antispasmodics & Prokinetics','medium','mcq','What is the dual receptor mechanism by which metoclopramide acts as a prokinetic in the upper GI tract?','["A. D2 receptor antagonism (removing inhibitory dopamine tone) and 5-HT4 receptor agonism (directly stimulating cholinergic release)","B. Muscarinic M3 agonism and H1 antagonism","C. NK1 antagonism and 5-HT3 antagonism in the myenteric plexus","D. Motilin receptor agonism and CGRP release from enteric neurons"]','A','Metoclopramide acts as a prokinetic through two complementary mechanisms: (1) D2 receptor antagonism — dopamine normally inhibits acetylcholine release in the enteric nervous system; blocking D2 removes this inhibition, restoring cholinergic propulsive activity; (2) 5-HT4 agonism — directly stimulates enteric neurons to release acetylcholine, further enhancing motility. The net effect is increased lower oesophageal sphincter tone, accelerated gastric emptying, and enhanced duodenal motility.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antispasmodics & Prokinetics','hard','mcq','Which antispasmodic would be MOST appropriate for a 70-year-old man with IBS and benign prostatic hyperplasia (BPH)?','["A. Hyoscine butylbromide — anticholinergic effects are mild as it is quaternary","B. Mebeverine — direct smooth muscle relaxant without anticholinergic effects","C. Dicycloverine (dicyclomine) — combined anticholinergic and direct smooth muscle effect","D. Atropine — most potent anticholinergic for maximum antispasm effect"]','B','In a patient with BPH, anticholinergic drugs (hyoscine, dicycloverine, atropine) can worsen urinary retention by blocking muscarinic receptors in the bladder, impairing detrusor contraction. Even quaternary anticholinergics like hyoscine butylbromide can cause some urinary hesitancy. Mebeverine has no anticholinergic activity, directly relaxing intestinal smooth muscle, making it the safest antispasmodic for patients with BPH, glaucoma, or other anticholinergic contraindications.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antispasmodics & Prokinetics','easy','mcq','Which prokinetic drug is used to treat gastroparesis in diabetic patients when domperidone is unavailable?','["A. Ondansetron","B. Lactulose","C. Metoclopramide","D. Erythromycin intravenously only"]','C','Metoclopramide is commonly used for diabetic gastroparesis. It accelerates gastric emptying through D2 antagonism and 5-HT4 agonism, and has the additional benefit of reducing associated nausea and vomiting. However, its use is limited by extrapyramidal side effects (particularly with prolonged use), and it should not be used for more than 5 days without careful review. In patients who cannot tolerate metoclopramide, domperidone or low-dose erythromycin are alternatives.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Antispasmodics & Prokinetics','medium','mcq','A patient takes hyoscine butylbromide for IBS. They develop blurred vision and dry mouth. Which receptor is responsible for these side effects?','["A. Nicotinic acetylcholine receptors at the neuromuscular junction","B. Beta-2 adrenergic receptors in the lacrimal glands","C. Alpha-1 adrenergic receptors in the iris","D. Muscarinic receptors in the ciliary body of the eye and salivary glands"]','D','Despite hyoscine butylbromide being a quaternary ammonium compound with reduced CNS penetration, some peripheral muscarinic side effects can still occur. Blurred vision results from muscarinic M3 receptor blockade in the ciliary body (impaired accommodation) and iris sphincter (mydriasis, increasing intraocular pressure risk). Dry mouth results from M3 blockade in salivary glands (reduced secretion). Urinary retention and constipation can also occur. These effects are dose-dependent.','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

-- SUBTOPIC 7: Drugs for Hepatic Encephalopathy (10 MCQs)
('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Drugs for Hepatic Encephalopathy','easy','mcq','What is the primary mechanism by which lactulose reduces ammonia in hepatic encephalopathy?','["A. Lactulose is metabolised by bacteria to acidify the colon, converting NH3 to NH4+ which cannot be absorbed","B. Lactulose directly binds ammonia in the gut lumen as an ion-exchange resin","C. Lactulose inhibits hepatic urea synthesis enzymes increasing urea excretion","D. Lactulose increases renal ammonia excretion by alkalinising the urine"]','A','In hepatic encephalopathy, colonic bacteria produce ammonia (NH3) from protein and urea, which crosses the BBB and causes neurological dysfunction. Lactulose is fermented by colonic bacteria to organic acids (lactic acid, acetic acid), lowering colonic pH. In an acidic environment, NH3 is protonated to NH4+ (ammonium ion), which is ionised, cannot cross the colonic mucosa, and is trapped in the lumen to be excreted in faeces. Lactulose also acts as a laxative, further reducing ammonia production time.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Drugs for Hepatic Encephalopathy','medium','mcq','Rifaximin is used in the secondary prevention of hepatic encephalopathy. What is its mechanism and key pharmacological property that makes it suitable?','["A. It is a systemic antibiotic that sterilises blood of ammonia-producing bacteria","B. It is a non-absorbable antibiotic that reduces ammonia-producing gut bacteria without significant systemic toxicity","C. It inhibits hepatic arginase, diverting nitrogen into the urea cycle","D. It is a selective 5-HT3 antagonist that reduces gut serotonin-driven ammonia production"]','B','Rifaximin is a rifamycin-derived antibiotic with minimal gastrointestinal absorption (<0.4%). It acts locally in the gut, inhibiting bacterial RNA polymerase and reducing the load of ammonia-producing bacteria in the colon. By reducing bacterial ammonia production, it decreases the ammonia burden reaching a failing liver. Key advantage over older gut antibiotics (neomycin): it is non-nephrotoxic and non-ototoxic. It is used in combination with lactulose for secondary prevention of hepatic encephalopathy episodes.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Drugs for Hepatic Encephalopathy','medium','mcq','Why is neomycin now rarely used for hepatic encephalopathy despite its historical effectiveness?','["A. It has been superseded by lactulose which is more effective for acute encephalopathy","B. Neomycin resistance among gut bacteria is now universal","C. Neomycin causes irreversible nephrotoxicity and ototoxicity when absorbed systemically","D. Neomycin stimulates ammonia-producing bacterial growth after initial depletion"]','C','Neomycin was historically used to reduce ammonia-producing gut bacteria in hepatic encephalopathy. However, despite being poorly absorbed from the gut, small but significant amounts can accumulate, particularly in patients with pre-existing renal impairment (common in advanced liver disease). Systemic neomycin causes nephrotoxicity and irreversible ototoxicity (sensorineural hearing loss). Given that rifaximin is equally effective without these risks, neomycin has fallen out of favour.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Drugs for Hepatic Encephalopathy','hard','mcq','A patient with cirrhosis and recurrent hepatic encephalopathy is treated with lactulose but continues to have episodes. What is the most evidence-based pharmacological addition?','["A. Add oral vancomycin 125mg QDS to further reduce gut ammonia producers","B. Add zinc supplementation alone as it restores urea cycle enzyme function sufficiently","C. Replace lactulose with polyethylene glycol for superior ammonia reduction","D. Add rifaximin 550mg BD to lactulose for secondary prophylaxis"]','D','Large randomised controlled trials (particularly the Bass et al. NEJM 2010 trial) demonstrated that rifaximin 550mg twice daily added to lactulose significantly reduces the risk of recurrent hepatic encephalopathy episodes compared to lactulose alone. This combination is now the standard of care for secondary prophylaxis. Rifaximin reduced the risk of a breakthrough episode by 58% compared to placebo in patients already on lactulose.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Drugs for Hepatic Encephalopathy','easy','mcq','What is the target stool frequency when titrating lactulose dose in a patient with hepatic encephalopathy?','["A. 2–3 soft stools per day","B. 1 formed stool per day","C. 4–6 watery stools per day","D. Lactulose dose is fixed at 30mL TDS regardless of response"]','A','Lactulose is titrated to achieve 2–3 soft stools per day. This frequency indicates adequate acidification of the colon (trapping ammonia) without excessive diarrhoea, which itself can worsen electrolyte imbalances and further precipitate encephalopathy. The dose typically ranges from 15–30mL three times daily, adjusted based on response. Both under-dosing (insufficient ammonia trapping) and over-dosing (diarrhoea → electrolyte disturbances → encephalopathy) must be avoided.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Drugs for Hepatic Encephalopathy','medium','mcq','How does zinc supplementation potentially benefit patients with hepatic encephalopathy?','["A. Zinc chelates ammonia in the blood, reducing plasma ammonia levels directly","B. Zinc acts as a cofactor for urea cycle enzymes (ornithine transcarbamylase), improving hepatic ammonia detoxification","C. Zinc inhibits bacterial urease in the gut, reducing ammonia production","D. Zinc stimulates glutamine synthetase in skeletal muscle, the primary ammonia detoxification pathway"]','B','Zinc is an essential cofactor for several urea cycle enzymes, including ornithine transcarbamylase (OTC). Zinc deficiency is common in cirrhosis (reduced dietary intake, increased urinary loss). Correcting zinc deficiency improves urea cycle enzyme activity and thus hepatic capacity to detoxify ammonia. Zinc supplementation (zinc acetate or zinc sulphate, 50mg elemental zinc three times daily) has shown modest benefit in reducing plasma ammonia and improving cognitive function in cirrhosis-related encephalopathy.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Drugs for Hepatic Encephalopathy','hard','mcq','Branched-chain amino acid (BCAA) supplementation is proposed for hepatic encephalopathy. What is the theoretical rationale?','["A. BCAAs are preferentially metabolised by the liver, reducing hepatic workload","B. BCAAs reduce portal hypertension by decreasing splanchnic blood flow","C. BCAAs compete with aromatic amino acids (AAAs) for transport across the blood-brain barrier, reducing neurotoxic AAA accumulation","D. BCAAs chelate ammonia in the muscle, converting it to glutamine for safe excretion"]','C','In hepatic encephalopathy, the ratio of branched-chain amino acids (valine, leucine, isoleucine) to aromatic amino acids (phenylalanine, tyrosine, tryptophan) in plasma is reduced. Aromatic amino acids are normally metabolised by the liver (which is failing), so they accumulate. Both BCAAs and AAAs compete for the same large neutral amino acid transporter (LAT1) to cross the BBB. Elevated AAAs lead to formation of false neurotransmitters (e.g., octopamine) and serotonin precursors (tryptophan → serotonin), contributing to encephalopathy. BCAAs are thought to partially restore this balance.','universal',false,'{year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Drugs for Hepatic Encephalopathy','medium','mcq','In acute hepatic encephalopathy, what is the most important precipitating factor to identify and correct pharmacologically?','["A. Dietary protein intake should be immediately restricted to zero","B. Sedative drugs should be prescribed immediately to prevent agitation","C. All hepatic encephalopathy requires immediate liver transplantation referral only","D. Common precipitants include GI bleeding, infections, electrolyte disturbances, and constipation — each requiring specific treatment"]','D','Hepatic encephalopathy is almost always precipitated by identifiable treatable factors: GI bleeding (increases ammonia load from blood in gut — treat with lactulose, consider rifaximin, find and stop bleeding), infections including SBP (treat with antibiotics), hyponatraemia/hypokalaemia (correct electrolytes), constipation (lactulose), dehydration (rehydrate), and drugs (benzodiazepines, opioids). Identifying and treating the precipitant alongside ammonia-lowering therapy is critical. Dietary protein restriction is NOT recommended for most patients.','universal',true,'{year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Drugs for Hepatic Encephalopathy','easy','mcq','Lactulose can be administered rectally in a patient with hepatic encephalopathy who cannot swallow. What is the rationale for this route?','["A. Rectal administration delivers lactulose directly to the colon where bacterial fermentation and ammonia trapping occur","B. Rectal administration allows direct absorption into the portal circulation for hepatic effects","C. Rectal lactulose is absorbed and then secreted into the colon by the liver","D. Rectal route achieves higher blood lactulose levels than oral administration"]','A','Rectal lactulose (as a retention enema, e.g., 300mL lactulose in 700mL water, retained for 1 hour) is effective in acute hepatic encephalopathy when the oral route is not feasible (coma, vomiting). The colon is precisely where lactulose exerts its therapeutic effect — bacterial fermentation to organic acids acidifies the colon, trapping NH3 as NH4+. No systemic absorption is needed for efficacy. This route can achieve rapid colonic acidification and ammonia trapping.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Drugs for Hepatic Encephalopathy','hard','mcq','Which of the following statements about the management of hepatic encephalopathy is INCORRECT?','["A. Lactulose should be titrated to produce 2–3 soft stools per day","B. Protein should be completely eliminated from the diet to prevent ammonia production","C. Rifaximin is effective as secondary prophylaxis when added to lactulose","D. Electrolyte imbalances such as hypokalaemia can precipitate encephalopathy and must be corrected"]','B','Complete dietary protein restriction is INCORRECT and harmful. It leads to muscle wasting and sarcopenia, which paradoxically worsens hepatic encephalopathy because muscle is a major site of ammonia detoxification via glutamine synthesis. Current guidelines recommend maintaining adequate protein intake (1.2–1.5g/kg/day), with a preference for vegetable-source and dairy proteins (less ammoniagenic than meat proteins). Small, frequent meals and a late-night snack are recommended to prevent catabolism.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

-- SUBTOPIC 8: Liver Disease Pharmacology (10 MCQs)
('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Liver Disease Pharmacology','easy','mcq','Which drug is the first-line treatment for ascites in patients with cirrhosis?','["A. Furosemide alone (loop diuretic)","B. Hydrochlorothiazide (thiazide diuretic)","C. Spironolactone (aldosterone antagonist)","D. Terlipressin (vasopressin analogue)"]','C','Spironolactone is the first-line diuretic for ascites in cirrhosis because secondary hyperaldosteronism is the dominant pathophysiological driver of sodium and water retention in decompensated liver disease. By blocking aldosterone receptors in the distal nephron, spironolactone reduces sodium reabsorption and promotes natriuresis. Initial dose is 100mg/day, titrated up to 400mg/day. Furosemide is added when spironolactone alone is insufficient, at a ratio of 100:40 (spironolactone:furosemide) to preserve electrolyte balance.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Liver Disease Pharmacology','medium','mcq','Why is the spironolactone:furosemide ratio of 100mg:40mg recommended when treating ascites?','["A. This ratio maximises diuresis by blocking all nephron segments simultaneously","B. This ratio is based on the hepatic metabolism rate of each drug in cirrhosis","C. This ratio achieves maximum portal pressure reduction","D. This ratio minimises electrolyte disturbances: spironolactone''s potassium-sparing effect counterbalances furosemide''s potassium-wasting effect"]','D','Furosemide (loop diuretic) causes potassium wasting, while spironolactone (aldosterone antagonist) is potassium-sparing. The 100mg:40mg ratio is empirically derived to maintain normokalemia while achieving adequate natriuresis. If the patient develops hyperkalaemia, furosemide dose can be increased relative to spironolactone. If hypokalaemia develops, spironolactone dose is increased relative to furosemide. Regular monitoring of electrolytes, renal function, and body weight is essential.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Liver Disease Pharmacology','medium','mcq','Non-selective beta-blockers (propranolol, carvedilol) are used in cirrhosis for which specific indication?','["A. Primary and secondary prophylaxis of oesophageal variceal bleeding","B. Prevention and management of hepatic encephalopathy","C. Treatment of ascites by reducing splanchnic blood flow","D. Prevention of spontaneous bacterial peritonitis in high-risk patients"]','A','Non-selective beta-blockers (NSBBs: propranolol, nadolol, carvedilol) reduce portal hypertension through two mechanisms: beta-1 blockade reduces cardiac output, and beta-2 blockade causes splanchnic vasoconstriction. Together, these reduce portal blood flow and portal pressure, lowering variceal wall tension and risk of rupture. NSBBs are recommended for primary prophylaxis (large varices without prior bleeding) and secondary prophylaxis (after a variceal bleed, combined with endoscopic band ligation). They do not treat ascites.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Liver Disease Pharmacology','hard','mcq','Terlipressin is used in acute variceal haemorrhage. What is its mechanism of action?','["A. Direct vasodilation of the portal vein reducing portal pressure acutely","B. V1 receptor agonism causing splanchnic vasoconstriction and reducing portal pressure","C. Inhibition of aldosterone synthesis reducing sodium retention","D. Somatostatin receptor agonism reducing glucagon release from the pancreas"]','B','Terlipressin is a synthetic vasopressin analogue (a prodrug of lysine vasopressin) that acts on V1 receptors on splanchnic arteriolar smooth muscle, causing vasoconstriction. This reduces splanchnic blood flow and thus reduces portal venous pressure, slowing or stopping variceal haemorrhage. Terlipressin has a longer half-life than vasopressin with fewer systemic vasoconstrictive side effects. It is also used in hepatorenal syndrome (HRS type 1) to improve renal perfusion.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Liver Disease Pharmacology','easy','mcq','N-acetylcysteine (NAC) is the antidote for which cause of acute liver failure?','["A. Alcohol-induced alcoholic hepatitis","B. Amanita phalloides mushroom poisoning","C. Paracetamol (acetaminophen) overdose","D. Hepatitis B-induced fulminant hepatic failure"]','C','N-acetylcysteine is the specific antidote for paracetamol-induced hepatotoxicity. Paracetamol overdose depletes hepatic glutathione stores, allowing the toxic metabolite NAPQI (N-acetyl-p-benzoquinone imine) to accumulate and bind covalently to hepatocyte proteins, causing centrilobular necrosis. NAC replenishes glutathione stores and provides cysteine as a glutathione precursor, detoxifying NAPQI. It is most effective within 8–10 hours of ingestion but has some benefit up to 24 hours or later.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Liver Disease Pharmacology','medium','mcq','Octreotide is used in acute variceal haemorrhage. How does it reduce portal pressure?','["A. It blocks V1 receptors on portal venous smooth muscle","B. It reduces cardiac output through beta-1 receptor blockade","C. It directly constricts the portal vein by alpha-adrenergic stimulation","D. It acts on somatostatin receptors to inhibit glucagon release, causing splanchnic vasoconstriction"]','D','Octreotide is a synthetic somatostatin analogue. By acting on somatostatin receptors (SSTR2, SSTR5) on pancreatic alpha cells and splanchnic vessels, octreotide inhibits glucagon secretion. Glucagon is a potent splanchnic vasodilator; its suppression leads to splanchnic vasoconstriction and reduced portal blood flow. It also directly inhibits splanchnic vasodilation. Octreotide is used as an adjunct to endoscopic therapy in acute variceal haemorrhage and has a better side effect profile than terlipressin.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Liver Disease Pharmacology','hard','mcq','A cirrhotic patient with ascites develops acute kidney injury and worsening hyponatraemia. Terlipressin is being considered for hepatorenal syndrome (HRS). What condition must be excluded first?','["A. Hypovolaemia from spontaneous bacterial peritonitis, diuretic excess, or GI blood loss, which should be treated with volume expansion first","B. Hepatitis C viraemia as terlipressin worsens viral replication","C. Hepatic encephalopathy grade 4 as terlipressin is contraindicated in coma","D. Portal vein thrombosis as terlipressin increases risk of clot extension"]','A','HRS is a diagnosis of exclusion — it must be distinguished from pre-renal AKI (volume depletion), which is treated with volume expansion (albumin infusion). Before diagnosing HRS and starting terlipressin, hypovolaemia from diuretic overuse, GI bleeding, or diarrhoea must be excluded by an albumin challenge (1g/kg/day for 2 days). If renal function improves with volume expansion, it was pre-renal AKI, not HRS. Terlipressin + albumin infusion is the pharmacological treatment for confirmed HRS type 1.','universal',true,'{year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Liver Disease Pharmacology','medium','mcq','Which statement about carvedilol versus propranolol for portal hypertension is correct?','["A. Propranolol is preferred because carvedilol causes severe hepatotoxicity","B. Carvedilol additionally blocks alpha-1 receptors, causing greater portal pressure reduction than propranolol","C. Carvedilol is purely a beta-1 selective blocker with less effect on splanchnic circulation","D. Both drugs are equally contraindicated in Child-Pugh class C cirrhosis"]','B','Carvedilol is a non-selective beta-blocker with additional alpha-1 adrenergic blocking activity. Alpha-1 blockade causes direct vasodilation of the hepatic and portal vasculature (reducing intrahepatic vascular resistance), in addition to the splanchnic vasoconstriction from beta-2 blockade. Studies show carvedilol reduces portal pressure by approximately 20% compared to 13% for propranolol, making it more effective. However, its vasodilatory effects may worsen hypotension in patients with low MAP (<55 mmHg).','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Liver Disease Pharmacology','easy','mcq','What is the main risk of using NSAIDs in a patient with decompensated liver disease and ascites?','["A. NSAIDs inhibit hepatic drug metabolism, increasing the risk of drug toxicity","B. NSAIDs directly damage hepatocytes causing further liver necrosis","C. NSAIDs cause prostaglandin inhibition, precipitating renal vasoconstriction and acute kidney injury or hepatorenal syndrome","D. NSAIDs stimulate aldosterone release, worsening ascites through sodium retention"]','C','In cirrhosis with ascites, renal perfusion is critically dependent on prostaglandin-mediated vasodilation of afferent arterioles (to compensate for reduced effective circulating volume and splanchnic vasodilation). NSAIDs inhibit COX-1 and COX-2, reducing prostaglandin synthesis, leading to afferent arteriolar constriction, further reducing GFR. This precipitates acute kidney injury and can trigger hepatorenal syndrome. NSAIDs are absolutely contraindicated in decompensated cirrhosis.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Liver Disease Pharmacology','hard','mcq','Spontaneous bacterial peritonitis (SBP) in cirrhosis is most commonly treated with which antibiotic, and what antibiotic prophylaxis is used for secondary prevention?','["A. Meropenem IV for treatment; co-trimoxazole for secondary prophylaxis","B. Metronidazole IV for treatment; amoxicillin for secondary prophylaxis","C. Vancomycin IV for treatment; rifaximin for secondary prophylaxis","D. Ceftriaxone IV for treatment; ciprofloxacin oral for secondary prophylaxis"]','D','Spontaneous bacterial peritonitis (SBP) is treated with intravenous cefotaxime or ceftriaxone (third-generation cephalosporin) for 5 days, combined with IV albumin (1.5g/kg on day 1, 1g/kg on day 3) to prevent hepatorenal syndrome. For secondary prophylaxis (after a first episode), oral norfloxacin 400mg/day or ciprofloxacin 500mg/day is used long-term. Trimethoprim-sulphamethoxazole is an alternative. Primary prophylaxis is recommended for cirrhotic patients with ascites protein <15g/L and Child-Pugh score ≥9.','universal',true,'{year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),

-- SUBTOPIC 9: Pancreatic Enzyme Supplements & Ursodeoxycholic Acid (10 MCQs)
('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Pancreatic Enzyme Supplements & Ursodeoxycholic Acid','easy','mcq','Pancreatin (Creon) contains which combination of enzymes?','["A. Lipase, amylase, and protease (pancrelipase)","B. Lipase and lactase only","C. Amylase and sucrase with trace lipase","D. Trypsin, chymotrypsin, and elastase only"]','A','Pancreatin preparations (e.g., Creon) contain a mixture of porcine-derived digestive enzymes: lipase (for fat digestion), amylase (for starch digestion), and protease/trypsin (for protein digestion). The lipase component is most critical for treating malabsorption and steatorrhoea, as fat digestion is the most severely impaired in exocrine pancreatic insufficiency. Different formulations (e.g., Creon 10000, Creon 25000) contain different lipase units.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Pancreatic Enzyme Supplements & Ursodeoxycholic Acid','medium','mcq','When should pancreatin (Creon) capsules be taken in relation to meals?','["A. 1 hour before meals to allow pre-gastric enzyme activation","B. During or immediately after meals, with capsules opened and sprinkled on food for infants","C. 2 hours after meals to coincide with intestinal phase of digestion","D. Only at bedtime as the enzymes act during overnight gastric emptying"]','B','Pancreatin should be taken during meals or immediately after. Food stimulates cholecystokinin (CCK) release, which in turn triggers pancreatic secretion and pyloric sphincter relaxation — the timing of enzyme supplementation should mimic this natural secretory pattern to maximise mixing with chyme in the duodenum. Enteric-coated microspheres protect enzymes from gastric acid. For infants and young children, capsules can be opened and microspheres sprinkled on acidic foods (apple sauce), but NOT mixed with alkaline foods (breast milk, formula) which would dissolve the coating.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Pancreatic Enzyme Supplements & Ursodeoxycholic Acid','hard','mcq','Fibrosing colonopathy is a rare but serious complication of pancreatin supplementation. What is the risk factor for this adverse effect?','["A. Concurrent use of PPIs that alkalinise the proximal small bowel","B. Use of pancreatin derived from bovine rather than porcine sources","C. High-dose pancreatin supplementation (>10,000 lipase units/kg/day), particularly in children with cystic fibrosis","D. Duration of pancreatin therapy exceeding 5 years regardless of dose"]','C','Fibrosing colonopathy is characterised by submucosal fibrosis of the colon causing strictures, predominantly affecting the right colon. It is associated with very high doses of pancreatin (particularly high-strength preparations providing >10,000 lipase units/kg/day) in children with cystic fibrosis. The exact mechanism is unclear but may involve direct mucosal injury from the methacrylic acid copolymer coating or the enzymes themselves. UK guidelines and prescribing information advise against exceeding this dose in children.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Pancreatic Enzyme Supplements & Ursodeoxycholic Acid','easy','mcq','Ursodeoxycholic acid (UDCA) is used in primary biliary cholangitis (PBC). What is its primary mechanism?','["A. Inhibiting bile acid synthesis in the liver by blocking HMG-CoA reductase","B. Inhibiting TNF-α-mediated hepatocyte apoptosis in biliary disease","C. Stimulating cAMP-mediated chloride secretion in bile ductules","D. Displacing hydrophobic toxic bile acids, improving bile flow, and reducing inflammation"]','D','UDCA is a hydrophilic bile acid that constitutes <5% of normal bile. When given therapeutically, it replaces cytotoxic hydrophobic bile acids (chenodeoxycholic acid, deoxycholic acid) in the bile acid pool, making bile less detergent-like and less injurious to biliary epithelium. It also stimulates bile secretion (choleretic effect) and has immunomodulatory and anti-apoptotic effects on cholangiocytes. In PBC, it slows disease progression, reduces liver biochemistry markers, and delays transplant requirements when started early.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Pancreatic Enzyme Supplements & Ursodeoxycholic Acid','medium','mcq','At what dose is ursodeoxycholic acid recommended for primary biliary cholangitis?','["A. 13–15 mg/kg/day in divided doses","B. 5–7 mg/kg/day in a single morning dose","C. 20–25 mg/kg/day as a single bedtime dose","D. 30 mg/kg/day divided into three doses"]','A','The recommended dose of UDCA for primary biliary cholangitis is 13–15 mg/kg/day, divided into 2–4 doses. At this dose, UDCA effectively replaces toxic bile acids in the bile acid pool and slows histological progression of PBC. Lower doses are used for gallstone dissolution (8–10 mg/kg/day). Higher doses have not shown additional benefit in PBC and may be associated with adverse effects. Approximately 40% of patients achieve a biochemical response (normalisation of ALP and bilirubin).','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Pancreatic Enzyme Supplements & Ursodeoxycholic Acid','medium','mcq','UDCA can be used to dissolve cholesterol gallstones. What type of gallstones are amenable to medical dissolution?','["A. Any gallstone regardless of composition or calcification","B. Small (<1cm), radiolucent (non-calcified), cholesterol-rich gallstones in a functioning gallbladder","C. Mixed pigment and cholesterol stones in patients with haemolytic anaemia","D. Gallstones in patients with total biliary obstruction awaiting ERCP"]','B','UDCA dissolves cholesterol gallstones by reducing cholesterol secretion into bile (desaturating bile) and directly solubilising cholesterol from the stone surface. It is only effective for: (1) small gallstones <1cm diameter; (2) radiolucent stones (absence of calcification on plain X-ray, indicating predominantly cholesterol composition); (3) in a functioning gallbladder with a patent cystic duct. Calcified (radio-opaque) stones, pigment stones, and non-functioning gallbladders do not respond. Treatment takes 6–24 months and stones can recur.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Pancreatic Enzyme Supplements & Ursodeoxycholic Acid','hard','mcq','A patient with cystic fibrosis and exocrine pancreatic insufficiency is on Creon 25000 with meals. Despite this, they continue to have steatorrhoea. Which intervention should be tried before increasing the pancreatin dose?','["A. Add a bile acid sequestrant (cholestyramine) to improve fat digestion","B. Switch from porcine pancreatin to bovine pancreatin for superior lipase activity","C. Add a PPI or H2 blocker to raise duodenal pH and improve enteric coating dissolution and enzyme activity","D. Administer pancreatin by nasojejunal tube to bypass gastric acid"]','C','In some patients, particularly those with cystic fibrosis, gastric acid hypersecretion or slow gastric emptying reduces duodenal pH, precipitating enteric-coated microsphere dissolution at a lower pH than intended, or inactivating uncoated enzyme preparations. Adding a PPI or H2 blocker raises duodenal pH, improves enteric coating dissolution at the correct site, and preserves enzyme activity. This should be tried before escalating pancreatin dose, since excessive doses risk fibrosing colonopathy.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Pancreatic Enzyme Supplements & Ursodeoxycholic Acid','medium','mcq','Which condition is the MOST common indication for pancreatin (Creon) supplementation?','["A. Coeliac disease causing villous atrophy","B. Small intestinal bacterial overgrowth","C. Irritable bowel syndrome with predominant diarrhoea","D. Chronic pancreatitis causing exocrine pancreatic insufficiency"]','D','Exocrine pancreatic insufficiency (EPI) is the primary indication for pancreatin supplementation. The most common causes of EPI requiring enzyme replacement are: chronic pancreatitis (especially alcohol-related), cystic fibrosis, and post-pancreatectomy states. EPI presents with steatorrhoea (bulky, pale, offensive, greasy stools), weight loss, and fat-soluble vitamin deficiencies. Pancreatin normalises digestion and absorption of fat, protein, and carbohydrates.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Pancreatic Enzyme Supplements & Ursodeoxycholic Acid','easy','mcq','UDCA is used as the mainstay of treatment in primary sclerosing cholangitis (PSC). What is the current evidence regarding its efficacy?','["A. UDCA at standard doses improves liver biochemistry in PSC but high-dose UDCA (28–30mg/kg/day) increases mortality and is harmful","B. UDCA at 13–15mg/kg/day significantly improves transplant-free survival in PSC","C. UDCA is equally effective as azathioprine for PSC","D. UDCA reverses strictures in PSC by dissolving biliary sludge"]','A','Unlike in PBC where UDCA clearly improves outcomes, the evidence in PSC is more complex. Standard-dose UDCA improves liver enzymes but has not shown consistent survival benefit. A large randomised trial of high-dose UDCA (28–30mg/kg/day) in PSC (Lindor et al.) showed increased rates of serious adverse events and death, leading to this dose being contraindicated in PSC. Current guidelines do not recommend routine UDCA for PSC outside clinical trials, though some centres still use standard doses.','universal',false,'{year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','Pancreatic Enzyme Supplements & Ursodeoxycholic Acid','hard','mcq','A patient taking pancreatin capsules for chronic pancreatitis complains that the capsules are difficult to swallow. The pharmacist advises opening the capsule and mixing the contents with food. What is the most important counselling point?','["A. The microspheres can be mixed with any food or liquid as the coating is resistant to all pH","B. Microspheres should only be mixed with acidic foods (pH < 5.5) to preserve the enteric coating; they must NOT be chewed or crushed","C. Opening the capsule renders the enzymes inactive and is therefore not recommended","D. The microspheres should be dissolved in warm milk before administration"]','B','The enteric coating on pancreatin microspheres protects lipase from gastric acid inactivation and allows dissolution in the alkaline duodenal environment (pH >5.5). If microspheres are mixed with foods of pH >5.5 (e.g., milk, infant formula, antacids), the coating may dissolve prematurely and enzymes will be inactivated by gastric acid. They should be mixed only with acidic foods (pH <5.5) such as unsweetened apple sauce or fruit juice. Crucially, microspheres must not be chewed or crushed as this destroys the enteric coating.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

-- SUBTOPIC 10: GI Drug Interactions & Adverse Effects (10 MCQs)
('{"medicine"}','Medicine','Gastroenterology','Pharmacology','GI Drug Interactions & Adverse Effects','easy','mcq','NSAIDs cause peptic ulceration primarily by which mechanism?','["A. Direct corrosive effect of the acidic NSAID molecule on gastric mucosa","B. Stimulation of gastrin secretion increasing acid output","C. Inhibition of COX-1 reducing prostaglandin E2 synthesis, impairing mucosal defence","D. H. pylori reactivation by suppressing mucosal immune defences"]','C','NSAIDs (aspirin, ibuprofen, diclofenac, naproxen) inhibit cyclo-oxygenase (COX) enzymes. COX-1 is constitutively expressed in the gastric mucosa and produces prostaglandin E2 (PGE2), which normally: stimulates mucus and bicarbonate secretion, maintains mucosal blood flow, and inhibits parietal cell acid secretion. COX-1 inhibition by NSAIDs reduces PGE2, impairing all three mucosal defence mechanisms, leading to ulceration. This occurs with systemic NSAID use, not just local contact — injectable and suppository NSAIDs also cause gastric ulcers.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','GI Drug Interactions & Adverse Effects','medium','mcq','A patient requires long-term NSAID therapy for rheumatoid arthritis and has a history of peptic ulcer. What is the most appropriate gastroprotective strategy?','["A. Prescribe enteric-coated aspirin instead of the NSAID","B. Advise the patient to take the NSAID only with meals, without any additional gastroprotection","C. Use the NSAID rectally as a suppository to avoid gastric contact","D. Co-prescribe a PPI (e.g., omeprazole 20mg daily) with the NSAID"]','D','Co-prescription of a PPI with NSAID therapy is the standard gastroprotective strategy for high-risk patients (previous ulcer, age >60, concurrent anticoagulant or corticosteroid use, high-dose NSAID). PPIs reduce intragastric acidity, promoting mucosal healing and preventing ulceration. Alternatively, misoprostol can be used but is less well tolerated (diarrhoea, uterine contractions). Enteric-coated NSAIDs do not prevent systemic prostaglandin inhibition and are not gastroprotective. Changing route of administration does not avoid systemic COX-1 inhibition.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','GI Drug Interactions & Adverse Effects','medium','mcq','COX-2 selective inhibitors (celecoxib, etoricoxib) reduce GI side effects compared to non-selective NSAIDs. What is the cardiovascular trade-off?','["A. COX-2 inhibitors increase thrombotic cardiovascular events by inhibiting vascular prostacyclin (PGI2) without reducing thromboxane A2 in platelets","B. COX-2 inhibitors significantly increase the risk of hypotension by reducing cardiac output","C. COX-2 inhibitors cause atrial fibrillation by prolonging the QT interval","D. COX-2 inhibitors have no cardiovascular effects and are safe in all cardiac patients"]','A','COX-2 is the inducible isoform responsible for prostaglandin synthesis in inflammation. Vascular endothelium expresses COX-2 and produces prostacyclin (PGI2), which is vasodilatory and anti-platelet. Platelets express only COX-1 and produce thromboxane A2 (TXA2), which is pro-platelet and vasoconstrictive. COX-2 inhibitors reduce vascular PGI2 (anti-thrombotic) without affecting platelet TXA2 (pro-thrombotic), tipping the balance towards thrombosis. This explains the increased risk of MI and stroke with COX-2 inhibitors (as shown with rofecoxib/Vioxx).','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','GI Drug Interactions & Adverse Effects','easy','mcq','Metformin causes GI side effects in approximately what proportion of patients?','["A. 5%","B. 30%","C. 15%","D. 60%"]','B','GI side effects occur in approximately 30% of patients starting metformin, including nausea, vomiting, diarrhoea, and abdominal discomfort. These are the most common reason for metformin discontinuation. Side effects are dose-related and most pronounced when starting treatment. They can be minimised by: starting at a low dose and titrating slowly, taking metformin with or after food, and using modified-release (MR) formulations which have a lower incidence of GI adverse effects.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','GI Drug Interactions & Adverse Effects','hard','mcq','Tetracyclines must not be taken with dairy products, antacids, or iron supplements. What is the pharmacokinetic mechanism behind this interaction?','["A. Dairy products induce CYP3A4, accelerating tetracycline metabolism","B. Antacids increase gastric pH, causing tetracycline ionisation and reduced passive absorption","C. Divalent and trivalent cations (Ca2+, Mg2+, Al3+, Fe2+/3+) form insoluble chelate complexes with tetracycline, drastically reducing absorption","D. Iron oxidises tetracycline molecules, converting them to inactive metabolites before absorption"]','C','Tetracyclines contain multiple keto and hydroxyl groups that readily chelate divalent and trivalent metal ions (calcium from dairy, magnesium and aluminium from antacids, iron from supplements, zinc, bismuth). These chelate complexes are insoluble at intestinal pH and cannot be absorbed, reducing tetracycline bioavailability by up to 60–80%. Tetracyclines should be taken on an empty stomach, at least 1–2 hours before or 4 hours after dairy products, antacids, or iron supplements.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','GI Drug Interactions & Adverse Effects','medium','mcq','Ciprofloxacin absorption is significantly reduced by co-administration with magnesium or aluminium-containing antacids. By approximately how much, and what is the mechanism?','["A. 20% reduction due to increased gastric pH reducing ionisation","B. 90% reduction due to antacid-mediated P-glycoprotein induction","C. 70% reduction due to antacid-induced delayed gastric emptying","D. 50% reduction due to chelation of ciprofloxacin with divalent/trivalent cations"]','D','Ciprofloxacin (a fluoroquinolone) has a hydroxypyridone carboxylic acid moiety that chelates divalent (Mg2+, Ca2+, Fe2+) and trivalent (Al3+) metal cations, forming poorly soluble complexes. This reduces ciprofloxacin oral bioavailability by approximately 50%. The same interaction occurs with iron supplements, sucralfate, and dairy products. Ciprofloxacin should be taken 2 hours before or 4–6 hours after these agents. Equivalent reductions also affect other fluoroquinolones (levofloxacin, moxifloxacin).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','GI Drug Interactions & Adverse Effects','medium','mcq','Oral iron supplementation causes which two characteristic and expected GI side effects?','["A. Constipation and black (tarry) stools","B. Diarrhoea and yellow discolouration of stool","C. Diarrhoea and haematemesis due to mucosal irritation","D. Nausea only with no change in stool colour"]','A','Oral iron (ferrous sulphate, ferrous gluconate, ferrous fumarate) commonly causes: (1) constipation — iron reduces intestinal motility, possibly by binding to and reducing bioavailability of hydrogen sulphide (a natural intestinal smooth muscle relaxant); (2) black/dark stools — unabsorbed iron sulphide colours stool black, mimicking melaena. Patients must be counselled that black stools are expected and not a sign of GI bleeding. Nausea and abdominal cramping also occur. Ferrous sulphate 200mg TDS is the standard preparation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','GI Drug Interactions & Adverse Effects','hard','mcq','Metformin is associated with lactic acidosis. In which GI-related clinical scenario is lactic acidosis risk particularly high?','["A. When metformin is taken with antacids reducing its absorption","B. When a patient develops acute severe gastroenteritis causing dehydration and acute kidney injury","C. When metformin is combined with lactulose reducing its enterohepatic recirculation","D. When metformin is taken with proton pump inhibitors reducing its renal clearance"]','B','Metformin inhibits mitochondrial complex I, slightly increasing lactate production. In normal circumstances, the kidney rapidly clears metformin, preventing accumulation. However, in acute kidney injury (AKI), metformin accumulates, causing marked inhibition of hepatic lactate metabolism and accumulation of lactic acid. Acute severe gastroenteritis → dehydration → reduced renal perfusion → AKI → metformin accumulation → lactic acidosis. Metformin should be temporarily stopped during acute illnesses that may compromise renal function.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','GI Drug Interactions & Adverse Effects','easy','mcq','Which strategy most effectively reduces the GI side effects of metformin when initiating therapy?','["A. Starting at maximum dose and reducing if side effects occur","B. Prescribing antiemetics prophylactically with every dose","C. Starting at a low dose (500mg with breakfast), titrating slowly, and taking with or after food","D. Advising the patient to take metformin on an empty stomach to maximise absorption"]','C','GI side effects of metformin (nausea, diarrhoea, abdominal pain) are minimised by: starting at a low dose (500mg once daily with the main meal), increasing gradually over 4–8 weeks to the therapeutic dose, and always taking with or immediately after food (this slows absorption, reducing peak plasma levels and GI exposure). Modified-release metformin (Glucophage SR) has a lower incidence of GI side effects due to slower, more sustained release and may be tried if standard metformin is not tolerated.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana Standard Treatment Guidelines 2017'),

('{"medicine"}','Medicine','Gastroenterology','Pharmacology','GI Drug Interactions & Adverse Effects','hard','mcq','A patient on warfarin develops a GI bleed requiring an NSAID for pain management. The prescriber considers celecoxib as a safer GI option. What drug interaction must be considered?','["A. Celecoxib is safe with warfarin as it does not affect CYP enzymes","B. Celecoxib competes with warfarin for albumin binding only, a minor interaction of no clinical significance","C. Celecoxib is contraindicated only with low-dose aspirin, not with warfarin","D. Celecoxib inhibits CYP2C9, increasing warfarin levels and bleeding risk, and should be used with caution with close INR monitoring"]','D','Celecoxib is a substrate and inhibitor of CYP2C9, the primary enzyme responsible for S-warfarin metabolism. Co-administration increases S-warfarin plasma levels, prolonging the INR and increasing bleeding risk. Moreover, celecoxib''s COX-2 inhibition of vascular PGI2 increases thrombotic risk, while even the mildly reduced platelet COX-1 inhibition does not fully protect against bleeding when on warfarin. If celecoxib must be used with warfarin, INR should be monitored closely, particularly in the first weeks of co-administration.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology, 7th Edition');
